VALIDATION_SIGNATURE = """def validate_evaluation_result_record(
    record: EvaluationResultRecord,
) -> EvaluationResultValidationResult:"""

def _section(text, heading):
    match = re.search(rf"^## {re.escape(heading)}\n(?P<body>.*?)(?=^## |\Z)", text, re.M | re.S)
    assert match
    return match.group("body")

def _numbered(body):
    return tuple(re.findall(r"^\d+\. `([^`]+)`$", body, re.M))

def _table(body):
    rows = [tuple(cell.strip().strip("`") for cell in line.strip("|").split("|")) for line in body.splitlines() if line.startswith("|") and "---" not in line]
    return tuple(rows[1:])

def _validate_document(text):
    assert text == EXPECTED_DOCUMENT
    assert text.startswith(f"# {TITLE}\n\nCanonical ID: {TITLE}\n")
    assert tuple(line[3:] for line in text.splitlines() if line.startswith("## ")) == HEADINGS
    assert _numbered(_section(text, "Exact public API")) == API
    assert _table(_section(text, "Exact enums")) == ENUMS
    payload = _section(text, "Immutable payloads")
    for name, fields, fixed in PAYLOAD_LINES:
        line = next(item for item in payload.splitlines() if item.startswith(f"- `{name}`"))
        assert tuple(re.findall(r"`([^`]+)`", line)[1:1 + len(fields)]) == fields
        assert all(item in line for item in fixed)
    assert _numbered(_section(text, "Evaluation result record")) == FIELDS
    result = _section(text, "Validation result and signatures")
    assert _numbered(result) == ("severity: EvaluationResultValidationSeverity", "passed: bool", "codes: tuple[EvaluationResultValidationCode, ...] = ()")
    assert MAPPING_SIGNATURE in result and VALIDATION_SIGNATURE in result
    mapping = _section(text, "Mapping keys, shape, and adaptation")
    assert _numbered(mapping) == tuple(field.split(":")[0] for field in FIELDS[:32])
    text_rules = _section(text, "Text, timestamp, posture, and supersession")
    required_line = next(line for line in text_rules.splitlines() if line.startswith("Required exact"))
    nullable_line = next(line for line in text_rules.splitlines() if line.startswith("Nullable text"))
    assert tuple(re.findall(r"`([^`]+)`", required_line)) == REQUIRED_TEXT
    assert tuple(re.findall(r"`([^`]+)`", nullable_line)[:3]) == NULLABLE_TEXT
    codes = _numbered(_section(text, "Validation codes"))
    assert tuple(item.split(" = ")[0] for item in codes) == CODES
    assert tuple(item.split('"')[1] for item in codes) == tuple(code.lower() for code in CODES)
    order = _section(text, "Validation order")
    assert all(f"({index}) {group}" in order for index, group in enumerate(GROUPS, 1))
    assert _numbered(_section(text, "Status and decision boundary")) == DECISIONS
    safety = _section(text, "Safety, dependencies, and non-goals")
    assert all(item in safety for item in NON_GOALS)
    assignments = _section(text, "Machine assignments")
    expected_assignments = ("actual_pr_374_merge_sha: `96935708eea4b197283a5a399c8ef57e63b6e795`", "base_sha: `96935708eea4b197283a5a399c8ef57e63b6e795`", "current_status: `request_prepared_implementation_not_approved`", "future_file_count: `2`", "public_symbol_count: `15`", "payload_count: `6`", "record_field_count: `33`", "required_mapping_key_count: `32`", "optional_mapping_key_count: `1`", "validation_code_count: `30`", "validation_group_count: `25`")
    assert all(item in assignments for item in expected_assignments)

def _assert_mutation_rejected(old, new, occurrence=1):
    assert EXPECTED_DOCUMENT.count(old) >= occurrence
    parts = EXPECTED_DOCUMENT.split(old)
    mutated = old.join(parts[:occurrence]) + new + old.join(parts[occurrence:])
    try:
        _validate_document(mutated)
    except AssertionError:
        return
    raise AssertionError((old, new))

def test_complete_independent_literal_contract():
    _validate_document(DOC_PATH.read_text(encoding="utf-8"))

def test_targeted_mutations_are_rejected_by_validator():
    mutations = (
        ("SCALAR_SCORE_RESULT", "SCALAR_RESULT"),
        ("scalar_score_result", "scalar_result"),
        ("`result_value: float`; `score_direction: str`", "`result_value: float`; `inserted: str`; `score_direction: str`"),
        ("`bin_id: str`; `bin_index: int`;", "`bin_index: int`;"),
        ("`reliability_value: float`; `resolution_value: float`", "`resolution_value: float`; `reliability_value: float`"),
        ("component_posture = reliability_resolution_uncertainty_required", "component_posture = changed"),
        ("1. `evaluation_result_id: str`\n2. `result_kind: EvaluationResultKind`", "1. `result_kind: EvaluationResultKind`\n2. `evaluation_result_id: str`"),
        ("mapping: object", "source: object"),
        ("EvaluationResultValidationResult,\n]:", "EvaluationResultValidationResult | None,\n]:"),
        ("31. `provenance`\n32. `result_created_at`", "31. `result_created_at`\n32. `provenance`"),
        ("`stratum_id`, `result_created_at`", "`result_created_at`, `stratum_id`"),
        ("text-invalid timestamp values therefore receive both codes", "text-invalid timestamp values receive only one code"),
        ("5. parse with `datetime.fromisoformat`;", "5. accept without parsing;"),
        ("total_considered_record_count == eligible_record_count + excluded_record_count + blocked_record_count", "total_considered_record_count >= eligible_record_count"),
        ("Suppress that code for invalid summary structure", "Do not suppress that code for invalid summary structure"),
        ("rank histogram requires `finite_comparable_ensemble`", "rank histogram requires `full_predictive_distribution`"),
        ("`paired_comparison_result` requires `paired_comparison`", "`paired_comparison_result` requires `candidate`"),
        ("ScalarScoreResultPayload |", "CalibrationBinResultPayload |"),
        ("0.0 <= result_value <= 1.0", "0.0 <= result_value <= 2.0"),
        ('1. `MISSING_REQUIRED_FIELD = "missing_required_field"`\n2. `UNEXPECTED_FIELD = "unexpected_field"`', '1. `UNEXPECTED_FIELD = "unexpected_field"`\n2. `MISSING_REQUIRED_FIELD = "missing_required_field"`'),
        ("(1) missing keys; (2) unexpected exact-string keys", "(1) unexpected exact-string keys; (2) missing keys"),
        ("request_prepared_implementation_not_approved", "approved"),
        ("score calculation;", ""),
        ("`market_id` remains non-routing", "`market_id` becomes routing"),
    )
    for old, new in mutations:
        _assert_mutation_rejected(old, new)

def test_static_test_safety_and_exact_read_allowlist():
    tree = ast.parse(SELF_PATH.read_text(encoding="utf-8"))
    imports = {alias.name.split(".")[0] for node in tree.body if isinstance(node, (ast.Import, ast.ImportFrom)) for alias in node.names}
    assert imports == {"ast", "pathlib", "re"}
    forbidden_names = {"eval", "exec", "compile", "__import__", "open", "input"}
    forbidden_attrs = {"write_text", "write_bytes", "open", "unlink", "rename", "replace", "mkdir", "rmdir", "touch", "chmod", "system", "popen", "run", "check_call", "check_output", "getenv", "putenv", "connect"}
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            assert node.func.id not in forbidden_names
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            assert node.func.attr not in forbidden_attrs
    read_roots = {node.func.value.id for node in ast.walk(tree) if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "read_text" and isinstance(node.func.value, ast.Name)}
    assert read_roots == {"DOC_PATH", "SELF_PATH", "ALLOWLIST_PATH"}

def test_direct_allowlist_integrity_and_observed_counts():
    source = ALLOWLIST_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    allowed_node = next(node for node in tree.body if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id == "ALLOWED_MARKET_ID_OCCURRENCE_LINES")
    assert isinstance(allowed_node.value, ast.Call) and len(allowed_node.value.args) == 1 and isinstance(allowed_node.value.args[0], ast.Dict)
    allowlist = ast.literal_eval(allowed_node.value.args[0])
    downstream_node = next(node for node in tree.body if isinstance(node, ast.Assign) and any(isinstance(target, ast.Name) and target.id == "_ARCH_ALIGN_03_DOWNSTREAM_ARTIFACTS" for target in node.targets))
    assert isinstance(downstream_node.value, ast.Set)
    downstream = ast.literal_eval(downstream_node.value)
    expected = ((str(DOC_PATH.relative_to(ROOT)), 1), (str(SELF_PATH.relative_to(ROOT)), 4))
    keys = [ast.literal_eval(key) for key in allowed_node.value.args[0].keys]
    for path, count in expected:
        assert list(downstream).count(path) == 1
        assert keys.count(path) == 1 and type(allowlist[path]) is int and allowlist[path] == count
        assert source.count(f'"{path}"') == 2
        assert (ROOT / path).read_text(encoding="utf-8").count("market_id") == count
    assert expected[0][0] != expected[1][0] and allowlist[expected[0][0]] != allowlist[expected[1][0]]
